-- 093: Heide Park Resort from RCDB via Carter's screenshots, 2026-10-31. All
-- nine rows; fills bare rows only (no length). Big Loop's screenshot was cut
-- above the opening date, so only its stats (Vekoma custom MK-1200 -> "Vekoma
-- Looper", as the site files the others). Safe to run twice.
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_edited', name, 6, json_object('id', id, 'fields', json_array('manu', 'model', 'h', 's', 'l', 'inv'), 'via', '093') FROM coasters WHERE name = 'Big Loop' AND park = 'Heide Park Resort' AND l IS NULL;
UPDATE coasters SET manu = 'Vekoma', model = 'Vekoma Looper', h = 98.4, s = 39.2, l = 2316.3, inv = 4 WHERE name = 'Big Loop' AND park = 'Heide Park Resort' AND l IS NULL;
